import {GAME} from './config.js';
import {BUILDINGS,SIZE,MODERN} from './catalog.js';

const SPEED=1.9,CARRY=20,STATES=new Set(['idle','walk','gather','return','waiting','blocked','move']);
const key=(x,y)=>x+':'+y,inside=(x,y)=>Number.isInteger(x)&&Number.isInteger(y)&&x>=0&&y>=0&&x<SIZE&&y<SIZE;
export function createWorkforce({groundAt,storageCap,log}){
 const collision=(s,x,y)=>!inside(x,y)||groundAt(s,x,y)!=='grass'||s.buildings.some(b=>x>=b.x&&x<b.x+BUILDINGS[b.type].size&&y>=b.y&&y<b.y+BUILDINGS[b.type].size);
 function spawn(s){const hq=s.buildings.find(b=>b.type==='hq'),ax=hq.x-1,ay=hq.y+BUILDINGS.hq.size+1;for(let r=0;r<SIZE;r++)for(let y=ay-r;y<=ay+r;y++)for(let x=ax-r;x<=ax+r;x++)if(!collision(s,x,y)&&!s.workforce.workers.some(w=>Math.hypot(w.x-x-.5,w.y-y-.5)<.6))return{x:x+.5,y:y+.5};throw Error('No hay una salida libre para los trabajadores.');}
 function add(s){const p=spawn(s),w={id:'w'+s.workforce.serial++,...p,cargo:0,resource:null,mode:'idle',order:null,path:[],moving:false,facing:0,retry:0};s.workforce.workers.push(w);return w;}
 function init(s){if(!s.workforce){s.workforce={version:1,serial:1,workers:[],deposits:{},training:[],delivered:0};for(let i=0;i<3;i++)add(s);}return s.workforce;}
 function node(s,x,y){if(!inside(x,y))return null;const kind=groundAt(s,x,y);if(!['tree','rock'].includes(kind)||s.buildings.some(b=>x>=b.x&&x<b.x+BUILDINGS[b.type].size&&y>=b.y&&y<b.y+BUILDINGS[b.type].size))return null;const total=kind==='tree'?120:180,remaining=s.workforce?.deposits[key(x,y)]??total,resource=kind==='tree'?'wood':MODERN?'gold':'metal';return remaining>0?{x,y,kind,total,remaining,resource,name:kind==='tree'?'Árbol':MODERN?'Yacimiento de oro':'Roca de piedra'}:null;}
 function path(s,w,goals){const valid=new Set(goals.filter(p=>!collision(s,p.x,p.y)).map(p=>p.y*SIZE+p.x));if(!valid.size)return null;const sx=Math.floor(w.x),sy=Math.floor(w.y);if(!inside(sx,sy))return null;const start=sy*SIZE+sx,parent=new Int16Array(SIZE*SIZE);parent.fill(-2);parent[start]=-1;const queue=[start];let end=-1;
  for(let at=0;at<queue.length;at++){const i=queue[at];if(valid.has(i)){end=i;break;}const x=i%SIZE,y=Math.floor(i/SIZE);for(const[nx,ny]of[[x+1,y],[x,y+1],[x-1,y],[x,y-1]]){if(!inside(nx,ny))continue;const n=ny*SIZE+nx;if(parent[n]!==-2||collision(s,nx,ny))continue;parent[n]=i;queue.push(n);}}
  if(end<0)return null;const result=[];for(let p=end;p!==start;p=parent[p])result.push({x:p%SIZE+.5,y:Math.floor(p/SIZE)+.5});result.reverse();if(!result.length)result.push({x:sx+.5,y:sy+.5});return result;
 }
 const adjacent=(x,y)=>[{x:x-1,y},{x:x+1,y},{x,y:y-1},{x,y:y+1}];
 function exits(s){const cells=[];for(const b of s.buildings.filter(b=>['hq','storage'].includes(b.type)&&b.hp>0&&b.job?.kind!=='build')){const n=BUILDINGS[b.type].size;for(let i=0;i<n;i++)cells.push({x:b.x-1,y:b.y+i},{x:b.x+n,y:b.y+i},{x:b.x+i,y:b.y-1},{x:b.x+i,y:b.y+n});}return cells;}
 function plan(s,w){w.path=[];w.moving=false;const n=w.order?.kind==='gather'?node(s,w.order.x,w.order.y):null;
  if(w.cargo>0&&(w.mode==='return'||w.mode==='waiting'||!n||w.cargo>=CARRY||w.resource!==n.resource)){const route=path(s,w,exits(s));w.mode=route?'return':'blocked';w.path=route||[];w.retry=1;return;}
  if(w.order?.kind==='move'){const route=path(s,w,[w.order]);w.mode=route?'move':'blocked';w.path=route||[];w.retry=1;return;}
  if(n){const occupied=new Set(s.workforce.workers.filter(other=>other!==w&&other.order?.kind==='gather'&&other.order.x===n.x&&other.order.y===n.y&&['walk','gather'].includes(other.mode)).map(other=>{const p=other.mode==='walk'?other.path.at(-1):other;return p?key(Math.floor(p.x),Math.floor(p.y)):'';}));const route=path(s,w,adjacent(n.x,n.y).filter(p=>!occupied.has(key(p.x,p.y))));w.mode=route?'walk':'blocked';w.path=route||[];w.retry=1;return;}
  w.order=null;w.mode='idle';
 }
 function assign(s,ids,x,y){init(s);if(s.battle)return{ok:false,message:'Los trabajadores se refugian durante el combate.'};const target=node(s,x,y);if(!target)return{ok:false,message:'Elige un árbol o un yacimiento con materiales.'};const list=s.workforce.workers.filter(w=>ids.includes(w.id));if(!list.length)return{ok:false,message:'Selecciona un trabajador.'};let assigned=0,unreachable=0;for(const w of list){if(!path(s,w,adjacent(x,y))){unreachable++;continue;}w.order={kind:'gather',x,y};w.mode=w.cargo>0?'return':'walk';plan(s,w);assigned++;}return{ok:assigned>0,message:assigned?assigned+' trabajador'+(assigned>1?'es':'')+' hacia '+GAME.resources[target.resource].name.toLowerCase()+'.'+(unreachable?' Otros no encuentran un camino.':''): 'No hay un camino libre hasta ese recurso.'};}
 function move(s,ids,x,y){init(s);x=Math.floor(x);y=Math.floor(y);if(s.battle||collision(s,x,y))return{ok:false,message:'Marca suelo libre para mover al trabajador.'};let count=0;for(const w of s.workforce.workers.filter(w=>ids.includes(w.id))){if(!path(s,w,[{x,y}]))continue;w.order={kind:'move',x,y};w.mode=w.cargo>0?'return':'move';plan(s,w);count++;}return{ok:count>0,message:count?'Orden recibida. La carga se entrega antes de cambiar de destino.':'No se encuentra un camino libre.'};}
 function stop(s,ids){init(s);if(s.battle)return{ok:false,message:'Espera a que termine el combate.'};let count=0;for(const w of s.workforce.workers.filter(w=>ids.includes(w.id))){w.order=null;w.mode=w.cargo>0?'return':'idle';plan(s,w);count++;}return{ok:count>0,message:count?'Trabajo detenido. Se entregará la carga pendiente.':'Selecciona un trabajador.'};}
 const capacity=s=>3+Math.floor((s.buildings.find(b=>b.type==='hq')?.level||1)/2)+s.buildings.filter(b=>b.type==='builders'&&b.hp>0&&!b.job).length*2;
 function hire(s){const f=init(s),count=f.workers.length+f.training.length,cost=hireCost(s);if(s.battle)return{ok:false,message:'Termina el combate antes de contratar.'};if(count>=capacity(s))return{ok:false,message:'Mejora el edificio principal o construye un taller para alojar más trabajadores.'};if(Object.entries(cost).some(([k,v])=>s.resources[k]<v))return{ok:false,message:'Faltan recursos para contratar.'};for(const[k,v]of Object.entries(cost))s.resources[k]-=v;const started=Math.max(s.time,f.training.at(-1)?.ends||0);f.training.push({id:'wc'+f.serial++,started,ends:started+18});return{ok:true,message:'Trabajador en preparación: 18 segundos.'};}
 const hireCost=s=>({gold:90+Math.max(0,(s.workforce?.workers.length||3)+(s.workforce?.training.length||0)-3)*25,supply:50});
 function tick(s,dt,simulate=true){const f=init(s);const done=f.training.filter(t=>t.ends<=s.time);f.training=f.training.filter(t=>t.ends>s.time);for(const t of done){try{add(s);log(s,MODERN?'Nuevo obrero disponible.':'Nuevo colono disponible.');}catch{t.ends=s.time+1;f.training.push(t);}}
  if(!simulate||s.battle){for(const w of f.workers)w.moving=false;return;}
  const rate=s.difficulty==='easy'?2:s.difficulty==='hard'?1.4:.85;
  for(const w of f.workers){w.moving=false;let remaining=dt;
   for(let guard=0;remaining>1e-7&&guard<1024;guard++){
    if(w.mode==='idle')break;
    if(w.mode==='waiting'||w.mode==='blocked'){const wait=Math.min(remaining,Math.max(0,w.retry));remaining-=wait;w.retry-=wait;if(w.retry>0)break;w.mode=w.cargo>0?'return':'walk';plan(s,w);if(w.mode==='blocked'){w.retry=1;continue;}}
    if(w.mode==='gather'){const n=w.order&&node(s,w.order.x,w.order.y);if(!n){w.order=null;w.mode=w.cargo>0?'return':'idle';plan(s,w);continue;}w.facing=Math.atan2(n.x+.5-w.x,n.y+.5-w.y);const amount=Math.max(0,Math.min(n.remaining,CARRY-w.cargo,remaining*rate));w.cargo=Math.min(CARRY,w.cargo+amount);w.resource=n.resource;f.deposits[key(n.x,n.y)]=Math.max(0,n.remaining-amount);remaining-=amount/rate;if(f.deposits[key(n.x,n.y)]<1e-7){f.deposits[key(n.x,n.y)]=0;if(!s.cleared.includes(key(n.x,n.y)))s.cleared.push(key(n.x,n.y));w.order=null;}if(w.cargo>=CARRY-1e-7||!w.order){w.mode='return';plan(s,w);}continue;}
    if(!w.path.length){if(w.mode==='walk'){w.mode='gather';continue;}if(w.mode==='move'){w.order=null;w.mode='idle';break;}if(w.mode==='return'){const space=Math.max(0,storageCap(s)-s.resources[w.resource]),amount=Math.min(w.cargo,space);if(amount>0){s.resources[w.resource]+=amount;w.cargo-=amount;f.delivered+=amount;s.stats.collected+=amount;s.xp+=amount/10;}if(w.cargo>1e-7){w.mode='waiting';w.retry=1;continue;}w.cargo=0;w.resource=null;plan(s,w);continue;}plan(s,w);continue;}
    const next=w.path[0];if(collision(s,Math.floor(next.x),Math.floor(next.y))){plan(s,w);continue;}const dx=next.x-w.x,dy=next.y-w.y,d=Math.hypot(dx,dy),distance=Math.min(d,SPEED*remaining);if(d>0){w.x+=dx/d*distance;w.y+=dy/d*distance;w.facing=Math.atan2(dx,dy);w.moving=true;}remaining-=distance/SPEED;if(d-distance<1e-7){w.x=next.x;w.y=next.y;w.path.shift();}else break;
   }
  }
 }
 function validate(s){if(s.workforce===undefined){init(s);return;}const f=s.workforce,finite=(n,min=0,max=SIZE)=>Number.isFinite(n)&&n>=min&&n<=max,validOrder=o=>!o||(['gather','move'].includes(o.kind)&&inside(o.x,o.y));
  if(!f||f.version!==1||!Number.isInteger(f.serial)||f.serial<1||!Array.isArray(f.workers)||f.workers.length>24||!Array.isArray(f.training)||f.training.length>24||!f.deposits||typeof f.deposits!=='object'||Array.isArray(f.deposits)||!finite(f.delivered,0,1e12))throw Error('Trabajadores no válidos.');
  const ids=new Set();for(const w of f.workers){if(!/^w[0-9]+$/.test(w.id)||ids.has(w.id)||!finite(w.x,0,SIZE-.001)||!finite(w.y,0,SIZE-.001)||!finite(w.cargo,0,CARRY+.001)||!STATES.has(w.mode)||!validOrder(w.order)||!Array.isArray(w.path)||w.path.length>SIZE*SIZE||w.path.some(p=>!p||!finite(p.x,0,SIZE-.001)||!finite(p.y,0,SIZE-.001))||!finite(w.retry,0,1)||!finite(w.facing,-Math.PI,Math.PI)||(w.resource!==null&&!Object.hasOwn(GAME.resources,w.resource))||(w.cargo>0&&w.resource===null))throw Error('Orden o carga de trabajador no válida.');ids.add(w.id);}
  for(const[k,v]of Object.entries(f.deposits)){const parts=k.split(':');if(parts.length!==2||!parts.every(p=>/^\d+$/.test(p))||!inside(+parts[0],+parts[1])||!finite(v,0,180))throw Error('Yacimiento no válido.');}
  if(Object.keys(f.deposits).length>SIZE*SIZE)throw Error('Demasiados yacimientos.');for(const t of f.training)if(!/^wc\d+$/.test(t.id)||!finite(t.started,0,1e12)||!finite(t.ends,t.started,1e12))throw Error('Contratación no válida.');
 }
 return{init,node,assign,move,stop,hire,hireCost,capacity,tick,validate,collision};
}
